<section id="privileges" data-access-panel><h2 tabindex="-1">Privilege Catalogue</h2><p>Built-in privileges protect application endpoints. Custom privileges can be assigned now; a new feature must explicitly check its custom privilege before it grants access.</p>
<?php if($can('privileges.manage')):?><details class="card"><summary>Create Custom Privilege</summary><form method="post"><label for="privilege-code">Code, starting with custom.</label><input id="privilege-code" name="code" placeholder="custom.example.view" maxlength="60" required><label for="privilege-description">Description</label><input id="privilege-description" name="description" maxlength="255" required><?php access_management_fields('create_privilege')?><p class="access-actions"><button>Create Privilege</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<div class="card scroll"><table><thead><tr><th>Code</th><th>Description</th></tr></thead><tbody><?php foreach($privileges as $privilege):?><tr><td><?=access_h($privilege['code'])?></td><td><?=access_h($privilege['description'])?></td></tr><?php endforeach?></tbody></table></div></section>